content.arguments:
{"command": ""=== 三次掉线时刻附近的系统事件 ==="
foreach ($t in @('20:20','21:21','22:25')) {
  $dt = [datetime]::Parse("2026-11-01 $t")
  "--- $t 前后 6 分钟 ---"
  Get-WinEvent -FilterHashtable @{LogName='System'; StartTime=$dt.AddMinutes(-6); EndTime=$dt.AddMinutes(6)} -ErrorAction SilentlyContinue |
    Where-Object { $_.LevelDisplayName -in 'Error','Warning','Critical' } |
    Select-Object -First 6 TimeCreated,Id,@{n='来源';e={$_.ProviderName}},@{n='消息';e={$_.Message.Substring(0,[Math]::Min(60,$_.Message.Length))}} |
    Format-Table -AutoSize
}", "description": "Check system events around each logout", "timeoutMs": 90000}

