{"command":"cd E:\qqbot
"=== 网络质量测试（60 秒）==="
"目标1: 腾讯 msfwifi.3g.qq.com  目标2: 模型服务 cn3.heilovehei.com"
""
$targets = @("msfwifi.3g.qq.com", "cn3.heilovehei.com")
