content.arguments:
{"command":"cd E:\qqbot
"=== TCP 连接质量测试：每个目标 15 次握手 ==="
$targets = @(
  @{n='腾讯 msfwifi'; h='msfwifi.3g.qq.com'; p=443},
  @{n='模型服务 cn3';  h='cn3.heilovehei.com'; p=443}
)
foreach ($t in $targets) {
  $ok=0; $fail=0; $times=@()
  for ($i=0; $i -lt 15; $i++) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $c = New-Object System.Net.Sockets.TcpClient
    try {
      $ar = $c.BeginConnect($t.h, $t.p, $null, $null)
      if ($ar.AsyncWaitHandle.WaitOne(3000)) { $c.EndConnect($ar); $ok++; $times += $sw.ElapsedMilliseconds }
      else { $fail++ }
    } catch { $fail++ } finally { $c.Close() }
    Start-Sleep -Milliseconds 300
  }
  $avg = if ($times.Count) { [math]::Round(($times | Measure-Object -Average).Average,0) } else { '-' }
  $mx  = if ($times.Count) { ($times | Measure-Object -Maximum).Maximum } else { '-' }
  "--- $($t.n) ---"
  "  成功 $ok/15  失败 $fail  平均 ${avg}ms  最大 ${mx}ms"
}","description":"Fast TCP handshake quality test","timeoutMs":150000}

