{"command":""=== STANDBYIDLE 与 VIDEOIDLE 当前值 ==="
foreach ($sub in @('SUB_SLEEP','SUB_VIDEO')) {
  $out = powercfg /query SCHEME_CURRENT $sub
  $inBlock = $false
  foreach ($line in $out) {
    if ($line -match "GUID 别名:\s*(STANDBYIDLE|VIDEOIDLE)") { $inBlock = $matches[1]; $acv=$null; $dcv=$null }
    if ($inBlock -and $line -match "当前交流电源设置索引:\s*(0x[0-9a-f]+)") { $acv = $matches[1] }
