    if ($inBlock -and $line -match "当前交流电源设置索引:\s*(0x[0-9a-f]+)") { $acv = $matches[1] }
    if ($inBlock -and $line -match "当前直流电源设置索引:\s*(0x[0-9a-f]+)") { $dcv = $matches[1]; "$inBlock : 交流(插电)=$([Convert]::ToInt32($acv,16))秒  直流(电池)=$([Convert]::ToInt32($dcv,16))秒"; $inBlock=$false }
  }
}

